# ==========================================================================
# dir_pages.py: builds the directory index, the firm profile pages and the
# "List your business" page (loaded by build.py, which supplies page(), form(), etc.)
# ==========================================================================

# Banner shown on sample pages only (empty once PLACEHOLDER is False)
bannerh='<p class="small" style="background:#fff7e0;border:1px solid #f0b429;padding:10px 14px;border-radius:8px">Sample listings: these are placeholder names to show how the directory will look. They are not real businesses.</p>' if PLACEHOLDER else ""
# Dropdown options for the filters
so="".join(f'<option value="{x[0]}">{x[1]}</option>' for x in SERV);lo="".join(f'<option value="{x[0]}">{x[1]}</option>' for x in LOC)
# One card per firm. data-* attributes hold searchable text, service slugs and location slugs for the filter script.
items="".join(f'<div class="item" data-q="{esc((f[1]+" "+f[2]).lower())}" data-s="{" ".join(f[3])}" data-l="{" ".join(f[4])}">{fcard(f)}</div>' for f in FIRMS)
# Filter script: shows or hides cards as the visitor types or changes a dropdown, and updates the result count.
js="""<script>(function(){var q=document.getElementById("dq"),s=document.getElementById("ds"),l=document.getElementById("dl"),n=document.getElementById("dn");function f(){var c=0;document.querySelectorAll("#dlist .item").forEach(function(i){var ok=(!q.value||i.dataset.q.indexOf(q.value.toLowerCase())>-1)&&(!s.value||(" "+i.dataset.s+" ").indexOf(" "+s.value+" ")>-1)&&(!l.value||(" "+i.dataset.l+" ").indexOf(" "+l.value+" ")>-1);i.style.display=ok?"":"none";if(ok)c++});n.textContent=c?c+" firm"+(c>1?"s":"")+" found":"No firms match. Try widening your search, or submit an enquiry and we will match you."}[q,s,l].forEach(function(e){e.addEventListener("input",f)})})()</script>"""
# Directory index page body: heading, filter box, result count, firm cards
dirbody=f'<div class="wrap">{crumbhtml([("Directory","/directory/")])}<h1>Victorian Surveyors &amp; Engineers Directory</h1><p class="lead">Browse licensed land surveyors, engineers and planners by service and location. Can\'t decide? <a href="{BASE}/contact/">We\'ll match you for free.</a></p>{bannerh}<div class="card filters"><label>Search<input id="dq" type="search" placeholder="Firm name"></label><label>Service<select id="ds"><option value="">All services</option>{so}</select></label><label>Location<select id="dl"><option value="">All of Victoria</option>{lo}</select></label></div><p id="dn" class="small" role="status">{len(FIRMS)} firms found</p><div id="dlist" class="grid">{items}</div><p>Are you a surveyor or engineer? <a href="{BASE}/list-your-business/">List your business</a>.</p></div>{js}'
# Directory index page (noindex while using sample firms)
page("directory/","Directory of Land Surveyors & Engineers in Victoria | "+NAME,"Browse land surveyors, civil engineers and town planners across Victoria by service and location, or get matched free.",dirbody,crumb=bc(("Directory","/directory/")),prio="0.9",noindex=PLACEHOLDER)
# One profile page per firm: about, services, areas, and a quote form pre-filled with the firm's name
for f in FIRMS:
    sl="".join(f'<li><a href="{BASE}/services/{x}/">{SN[x]}</a></li>' for x in f[3]);ll="".join(f'<li><a href="{BASE}/locations/{x}/">{LN[x]}</a></li>' for x in f[4])
    b=f'<div class="wrap pg"><article>{crumbhtml([("Directory","/directory/"),(f[1],"/directory/"+f[0]+"/")])}<h1>{f[1]}</h1><p class="lead">{f[2]} · Victoria</p>{bannerh}<h2>About</h2><p>{f[5]}</p><h2>Services</h2><ul class="ticks">{sl}</ul><h2>Areas serviced</h2><ul class="ticks">{ll}</ul><p class="small">We introduce licensed professionals only. Licence details are checked before a firm is listed.</p></article><aside>{form("Enquiry for "+f[1]+". ","Request a quote from this firm")}</aside></div>'
    # LocalBusiness structured data only for real listings (never for samples)
    sch=[] if PLACEHOLDER else [{"@type":"LocalBusiness","name":f[1],"areaServed":[LN[x] for x in f[4]],"description":f[5],"url":SITE+"/directory/"+f[0]+"/"}]
    page(f"directory/{f[0]}/",f"{f[1]} | {f[2]} in Victoria | {NAME}",f"{f[1]}: {f[2].lower()} serving {', '.join(LN[x] for x in f[4][:3])}. Request a quote.",b,sch,bc(("Directory","/directory/"),(f[1],"/directory/"+f[0]+"/")),prio="0.7",noindex=PLACEHOLDER)
# Sends the listing application to Formspree without leaving the page
lj="""<script>document.getElementById("lf").addEventListener("submit",function(e){e.preventDefault();var f=e.target,m=document.getElementById("lm");m.textContent="Sending…";fetch(f.action,{method:"POST",body:new FormData(f),headers:{Accept:"application/json"}}).then(function(r){if(r.ok){f.reset();m.textContent="Thanks! We will be in touch to verify your details."}else throw 0}).catch(function(){m.textContent="Sorry, something went wrong. Please try again."})})</script>"""
# Application page for firms wanting to be listed
page("list-your-business/","List Your Surveying or Engineering Business | "+NAME,"Surveyors, engineers and planners: get listed in our Victorian directory and receive enquiries from landowners and developers.",
f'<div class="narrow">{crumbhtml([("List your business","/list-your-business/")])}<h1>List Your Business in the Directory</h1><p class="lead">Reach landowners and developers looking for licensed surveyors, engineers and planners in Victoria.</p><ul class="ticks"><li>A profile page for your firm</li><li>Appear on service and location pages</li><li>Receive matched enquiries</li></ul><form class="quote" id="lf" action="https://formspree.io/f/xwllwjvz" method="POST"><h2>Apply to be listed</h2><input type="hidden" name="type" value="Directory listing application"><label for="bn">Business name</label><input id="bn" name="business" required><label for="be">Contact email</label><input id="be" name="email" type="email" required><label for="bl">Licence / registration number</label><input id="bl" name="licence" required><label for="bs">Services you offer</label><textarea id="bs" name="services" rows="3" required></textarea><label for="ba">Areas you cover</label><input id="ba" name="areas" required><button class="btn" type="submit">Submit application</button><p class="form-msg" id="lm" role="status"></p></form></div>{lj}',crumb=bc(("List your business","/list-your-business/")),prio="0.6")
